        let tomorrow = today.succ_opt().unwrap();
        let start_naive = today.and_hms_opt(23, 0, 0).unwrap();
        let stop_naive = tomorrow.and_hms_opt(11, 0, 0).unwrap();
        let start = Local
            .from_local_datetime(&start_naive)
