                is_private: false,
                active: true,
                at: start,
                created_at: start,
                color: String::new(),
                billable: None,
            }),
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn aggregates_rounded_billable_stopped_entries_and_sorts() {
        let entries = vec![
            entry(1, 7 * 60, true, Some(1), Some("Zeta")),
            entry(2, 22 * 60, true, Some(1), Some("Alpha")),
            entry(3, 15 * 60, true, Some(1), Some("Alpha")),
